00140:   // ── C: gemeinsame Farbabstimmung ---------------------------------------
00141:   // CSS filter DIREKT auf #kamera (= Hintergrund+Koerper+Kopf+Mund+Augen als
00142:   // EINE bereits zusammengesetzte Ebene, siehe buehne.html-Kommentar zu
00143:   // #kamera). Das ist ein echtes UMFAERBEN der fertigen Komposition, keine
00144:   // zusaetzliche Flaeche -- exakt die Lehre aus den zweimal gescheiterten
00145:   // #farbschicht/#wasserlinie-Versuchen ("nie wieder eine Auflage auf dem
00146:   // Gesicht"). Ein CSS-`filter` kann per Definition nichts "auflegen", er
00147:   // faerbt vorhandene Pixel um.
00148:   var GRUND_FILTER = "sepia(0.05) saturate(1.05) contrast(1.03) hue-rotate(-2deg)";
00149:   function injiziereFarbabstimmung(kamera) {
00150:     kamera.style.transition =
00151:       (kamera.style.transition ? kamera.style.transition + ", " : "") + "filter 4s ease";
00152:     kamera.style.filter = GRUND_FILTER;
00153:   }
00154: 
00155:   // Bonus: Stimmung leicht aus echten, gemessenen Werten faerben -- KEIN
00156:   // erfundenes Feld, nur was /api/status tatsaechlich liefert
00157:   // (broadcast_value, ueberraschung), vorher per curl geprueft. Eigene,
00158:   // langsame Poll-Schleife (6s) statt in die bestehende Buehnen-Schleife
00159:   // einzugreifen -- diese Datei fasst nur an, was sie selbst injiziert hat.
00160:   function starteZustandsPoll() {
00161:     var kamera = document.getElementById("kamera");
00162:     if (!kamera) return;
00163:     async function schritt() {
00164:       try {
00165:         var r = await fetch("/api/status");
00166:         var d = await r.json();
00167:         var b = (d && d.buehne) || {};
00168:         var hue = -2,
00169:           sat = 1.05;
00170:         if (typeof b.ueberraschung === "number") {
00171:           var u = Math.max(0, Math.min(1, b.ueberraschung));
00172:           hue = -2 + u * 8; // ruhig: leicht kuehl -- angespannt: leicht waermer/roeter
00173:         }
00174:         if (typeof b.broadcast_value === "number") {
00175:           var t = Math.max(0, Math.min(3, b.broadcast_value)) / 3;
00176:           sat = 1.02 + t * 0.06;
00177:         }
00178:         kamera.style.filter =
00179:           "sepia(0.05) saturate(" + sat.toFixed(3) + ") contrast(1.03) hue-rotate(" + hue.toFixed(2) + "deg)";
00180:       } catch (e) {
00181:         /* kein Status erreichbar -> Grundfarbe (GRUND_FILTER) bleibt stehen */
00182:       }
00183:     }
00184:     schritt();
00185:     setInterval(schritt, 6000);
00186:   }
00187: })();
